def frame(n, timing, visual, camera, audio, text, purpose):
    return {'frame': n, 'timeWindow': timing, 'visualAction': visual, 'camera': camera, 'audio': audio, 'onScreenText': text, 'purpose': purpose}

def storyboard(x):
    # Twelve detail frames: each is a planning direction, not a final shoot script or claim clearance.
    return [
        frame(1,'00:00–00:03',x['hook'],'Graphic macro or decisive establishing shot','First sensory sound; no music lyric required','Working title only','Interrupt the scroll with a simple premise.'),
        frame(2,'00:03–00:07',x['world'],'Slow reveal / location texture','Natural ambience enters','Location/client text: proposed/TBC','Set a human environment without implying an endorsement.'),
        frame(3,'00:07–00:10',x['sensory'],'Macro cut sequence','Layered diegetic sensory sounds','No claim text','Make the product/category felt before it is explained.'),
        frame(4,'00:10–00:14',x['friction'],'Medium character or object problem shot','Music pauses or narrows','Question prompt, client-approved only','Name the real decision friction.'),
        frame(5,'00:14–00:18',x['reveal'],'Clean transition to visual system/card','Sound resolves into one simple motif','One approved proposition line','Show the route, not an exaggerated solution.'),
        frame(6,'00:18–00:23',x['craft'],'Macro craft/action coverage','Technique sounds foregrounded','Factual field placeholders only','Give visual credibility while keeping facts approval-gated.'),
        frame(7,'00:23–00:27',x['human'],'Over-shoulder or shared-table shot','Brief authentic dialogue/room tone','No testimonial or result statement','Make participation feel voluntary and human.'),
        frame(8,'00:27–00:31',x['choice'],'Insert of hand choosing a card/route','Single confirmation tone','Optional next-step prompt','Show a transparent conversion moment.'),
        frame(9,'00:31–00:35',x['payoff'],'Wider emotional payoff shot','Music opens gently','No quantitative claim','Reward the decision with atmosphere, not a sales promise.'),
        frame(10,'00:35–00:39',x['scale'],'Pattern montage or top shot','Rhythmic edit','Category/series title, subject to approval','Suggest a broader world without asserting scale or attendance.'),
        frame(11,'00:39–00:42',x['responsible'],'Clean legal/fact-card composition','Music strips back for legibility','Legal/claims/availability placeholders','Hold the boundary between creative promise and substantiated information.'),
        frame(12,'00:42–00:45',x['cta'],'Endboard with a calm human/object final image','Final resolved sound','Client-approved CTA + QR/URL placeholder','Deliver one voluntary next action.')
    ]

commercials = []
for x in items:
    x = dict(x)
    x['storyboardStatus'] = 'Concept storyboard direction: 12 frames; all pack, product, claim, cast, music, venue and end-card details proposed/TBC.'
    x['storyboard'] = storyboard(x)
    commercials.append(x)

